bool Validator::finish() {
    /* charged slots cover [0,cells) densely; no unused nonempty data */
    for (int s = 0; s < RAM_NUM; ++s) {
        for (uint32_t c = 0; c < d->cells[s]; ++c)
            if (cover[s][c] < 0) return FAILAT();
        if (d->cells[s] & 1u) {
            const Row256& row = d->banks[s][d->cells[s] / 2];
            if (!pk_zero(row, 128, 128)) return FAILAT();      /* final upper half zero */
        }
    }
    for (size_t i = 0; i < children.size(); ++i) {
        const ChildRef& cr = children[i];
        if (cr.stage < 0 || cr.stage >= RAM_NUM) return FAILAT();
        if (cr.cell >= d->cells[cr.stage]) return FAILAT();
        int32_t id = cover[cr.stage][cr.cell];
        if (id < 0) return FAILAT();
        if (nodes[id].cell != cr.cell) return FAILAT();         /* exact slot start */
        if (id != cr.node) return FAILAT();
    }

    /* owned prefixes, bottom-up (child stages are strictly lower) */
    std::vector<int32_t> by_stage[RAM_NUM];
    for (size_t i = 0; i < nodes.size(); ++i)
        by_stage[nodes[i].stage].push_back(static_cast<int32_t>(i));
    for (int s = 0; s < RAM_NUM; ++s) {
        for (size_t j = 0; j < by_stage[s].size(); ++j) {
            int32_t idx = by_stage[s][j];
            ValNode& n = nodes[idx];
            uint32_t owned;
            if (n.type == TYPE4) owned = 1;
            else if (n.type == TYPE5) owned = 2;
            else owned = scamp_popcount64(n.pattern);
            for (uint8_t k = 0; k < n.ch_count; ++k) {
                const ChildRef& cr = children[n.ch_start + k];
                if (cr.node < 0) return FAILAT();
                const ValNode& ch = nodes[cr.node];
                if (ch.parent != idx) return FAILAT();          /* exactly one parent */
                owned += ch.owned;
                if (owned > SCAMP_PREFIX_LIMIT) return FAILAT();
            }
            n.owned = owned;
            if (n.type <= TYPE3 && owned < 3) return FAILAT();  /* larger subtrees only */
            if (n.type == TYPE4 && owned != 1) return FAILAT();
            if (n.type == TYPE5 && owned != 2) return FAILAT();
        }
    }

    /* complete FIB: distinct and bounded */
    std::sort(fib.begin(), fib.end(), [](const ScampPrefix& a, const ScampPrefix& b) {
        if (a.addr != b.addr) return a.addr < b.addr;
        return a.len < b.len;
    });
    for (size_t i = 1; i < fib.size(); ++i)
        if (fib[i].addr == fib[i - 1].addr && fib[i].len == fib[i - 1].len) return FAILAT();
    if (fib.size() > SCAMP_PREFIX_LIMIT) return FAILAT();

    /* global BMP fallbacks */
    {
        LiveFib lf;
        for (size_t i = 0; i < fib.size(); ++i) lf.put(fib[i].addr, fib[i].len, fib[i].hop);
        for (size_t i = 0; i < nodes.size(); ++i) {
            const ValNode& n = nodes[i];
            nexthop_t v = lf.lookup_bounded(n.region, n.depth);
            uint32_t want = (v == LPM_INVALID_NH) ? SCAMP_BMP_NULL : static_cast<uint32_t>(v);
            if (n.bmp != want) return FAILAT();
        }
    }

    /* NI dictionary: distinct used patterns, increasing order */
    {
        std::vector<uint64_t> used;
        for (size_t i = 0; i < nodes.size(); ++i)
            if (nodes[i].type <= TYPE3) used.push_back(nodes[i].pattern);
        std::sort(used.begin(), used.end());
        used.erase(std::unique(used.begin(), used.end()), used.end());
        if (used.size() != d->bitmaps.size()) return FAILAT();
        for (size_t i = 0; i < used.size(); ++i) if (used[i] != d->bitmaps[i]) return FAILAT();
    }
    /* NI arrays: disjoint, no holes, complete coverage */
    {
        std::vector<unsigned char> mark(d->nexthops.size(), 0);
        for (size_t i = 0; i < nodes.size(); ++i) {
            const ValNode& n = nodes[i];
            if (n.type > TYPE3) continue;
            uint32_t pc = scamp_popcount64(n.pattern);
            if (pc == 0) {
                if (n.ni_base != 0) return FAILAT();
                continue;
            }
            if (static_cast<uint64_t>(n.ni_base) + pc > mark.size()) return FAILAT();
            for (uint32_t k = 0; k < pc; ++k) {
                if (mark[n.ni_base + k]) return FAILAT();
                mark[n.ni_base + k] = 1;
            }
        }
        for (size_t i = 0; i < mark.size(); ++i) if (!mark[i]) return FAILAT();
    }
